def complex_function(data):
    result = 0
    for item in data:
        if item > 0:
            if item < 10:
                result += item
            elif item < 20:
                result += item * 2
            else:
                result += item * 3
        elif item < 0:
            if item > -10:
                result -= item
            else:
                result -= item * 2
    return result

